do $$ declare t text; begin foreach t in array array['kunjungan','isu_strategis','rekomendasi','media_monitoring','agenda'] loop execute format('drop policy if exists public_insert on public.%I',t);execute format('drop policy if exists public_update on public.%I',t);execute format('create policy public_insert on public.%I for insert to anon with check (true)',t);execute format('create policy public_update on public.%I for update to anon using (true) with check (true)',t);execute format('grant select, insert, update on public.%I to anon',t);end loop;end $$;
drop policy if exists pin_settings_insert on public.tim_analisis;drop policy if exists pin_settings_update on public.tim_analisis;create policy pin_settings_insert on public.tim_analisis for insert to anon with check((select private.ah_admin_session_valid()));create policy pin_settings_update on public.tim_analisis for update to anon using((select private.ah_admin_session_valid()))with check((select private.ah_admin_session_valid()));grant insert,update on public.tim_analisis to anon;
drop policy if exists ah_team_assets_insert on storage.objects;drop policy if exists ah_team_assets_update on storage.objects;drop policy if exists ah_team_assets_delete on storage.objects;create policy ah_team_assets_insert on storage.objects for insert to anon with check(bucket_id='team-assets' and(select private.ah_admin_session_valid()));create policy ah_team_assets_update on storage.objects for update to anon using(bucket_id='team-assets' and(select private.ah_admin_session_valid()))with check(bucket_id='team-assets' and(select private.ah_admin_session_valid()));create policy ah_team_assets_delete on storage.objects for delete to anon using(bucket_id='team-assets' and(select private.ah_admin_session_valid()));
